package com.corecs.dbms.parser;
import com.corecs.dbms.model.*;import java.util.*;
public class MiniSqlParser {
  public ParsedQuery parse(List<String> t){if(t.isEmpty())throw new IllegalArgumentException("No SQL tokens");String op=t.get(0).toUpperCase();return switch(op){case "CREATE"->create(t);case "INSERT"->insert(t);case "SELECT"->select(t);case "UPDATE"->update(t);case "DELETE"->delete(t);default->throw new IllegalArgumentException("Unsupported SQL command: "+op);};}
  private ParsedQuery create(List<String> t){need(t,4,"CREATE TABLE table (...)");if(!t.get(1).equalsIgnoreCase("TABLE"))throw new IllegalArgumentException("Expected TABLE after CREATE");String table=t.get(2);List<String> cols=new ArrayList<>();for(int i=4;i<t.size();i++){if(t.get(i).equals(")")||t.get(i).equals(";"))break;if(t.get(i).equals(","))continue;String name=t.get(i++);String type=t.get(i);boolean pk=false;if(i+1<t.size()&&t.get(i+1).equalsIgnoreCase("PRIMARY")){i+=2;pk=true;}cols.add(name+":"+type+(pk?":PK":""));}return new ParsedQuery("CREATE",table,cols,List.of(),null,List.of(),List.of());}
  private ParsedQuery insert(List<String> t){need(t,6,"INSERT INTO table VALUES (...)");String table=t.get(2);int start=indexOfIgnore(t,"VALUES");if(start<0)throw new IllegalArgumentException("Expected VALUES");List<String> vals=new ArrayList<>();for(int i=start+1;i<t.size();i++){String x=t.get(i);if(!x.equals("(")&&!x.equals(")")&&!x.equals(",")&&!x.equals(";"))vals.add(x);}return new ParsedQuery("INSERT",table,List.of(),List.of(vals),null,List.of(),List.of());}
  private ParsedQuery select(List<String> t){int from=indexOfIgnore(t,"FROM");if(from<0)throw new IllegalArgumentException("SELECT requires FROM");List<String> cols=new ArrayList<>();for(int i=1;i<from;i++)if(!t.get(i).equals(","))cols.add(t.get(i));String table=t.get(from+1);return new ParsedQuery("SELECT",table,cols,List.of(),where(t,from+2),List.of(),List.of());}
  private ParsedQuery update(List<String> t){if(t.size()<6||!t.get(2).equalsIgnoreCase("SET"))throw new IllegalArgumentException("UPDATE table SET column=value [WHERE ...]");String table=t.get(1);List<String> c=new ArrayList<>(),v=new ArrayList<>();int i=3;while(i<t.size()&&!t.get(i).equalsIgnoreCase("WHERE")&&!t.get(i).equals(";")){if(t.get(i).equals(",")){i++;continue;}c.add(t.get(i));i++;if(i<t.size()&&t.get(i).equals("="))i++;if(i>=t.size())throw new IllegalArgumentException("Missing SET value");v.add(t.get(i++));}return new ParsedQuery("UPDATE",table,List.of(),List.of(),where(t,i),c,v);}
  private ParsedQuery delete(List<String> t){if(t.size()<3||!t.get(1).equalsIgnoreCase("FROM"))throw new IllegalArgumentException("DELETE FROM table [WHERE ...]");return new ParsedQuery("DELETE",t.get(2),List.of(),List.of(),where(t,3),List.of(),List.of());}
  private WhereClause where(List<String> t,int start){int i=indexOfIgnoreFrom(t,"WHERE",start);if(i<0)return null;if(i+3>=t.size())throw new IllegalArgumentException("WHERE requires column operator value");return new WhereClause(t.get(i+1),t.get(i+2),t.get(i+3).replace(";",""));}
  private int indexOfIgnore(List<String> t,String x){return indexOfIgnoreFrom(t,x,0);} private int indexOfIgnoreFrom(List<String> t,String x,int s){for(int i=s;i<t.size();i++)if(t.get(i).equalsIgnoreCase(x))return i;return -1;} private void need(List<String> t,int n,String msg){if(t.size()<n)throw new IllegalArgumentException(msg);}
}
